INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_qgrd_1', 'oa_qgrd_drainage', 'Verification of Garden Drainage Components and Nursery Stock on Arrival', 'Drainage channels, manhole covers, paving accessories, and nursery stock should be checked by batch against their locations and maintenance conditions; arrival sign-off cannot prove grading, drainage-channel connection, or survival acceptance.', 'https://landscape.example/xian/material-arrival', '2026-06-01');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_qgrd_2', 'oa_qgrd_brand', 'How to Itemize Grading, Connection Elevation Difference, and Rain-Test Evidence', 'The benchmark, slope direction, drainage-channel connection elevation, and drainage time after rain should each be documented separately; a single fair-weather observation cannot replace ponding verification after effective rainfall.', 'https://greenall.example/service/drainage-evidence', '2026-06-05');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_qgrd_3', 'oa_qgrd_card', 'Preauthorization and Reversal Status for Drainage-Accessory Merchants', 'Accessory preauthorization, duplicate-charge investigation, and final reversal are three separate statuses; the budget should retain the normal amount due until the card shows a clear negative entry.', 'https://card.example/drainage-transaction-status', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_qgrd_4', 'oa_qgrd_brand', 'Key Points for Listing Garden Stone, Manhole Covers, and Surplus Nursery Stock', 'Describe stone by batch and size, manhole covers by material and load rating, and nursery stock by specifications and maintenance status; funds on the platform do not count as surplus-material proceeds until they are settled.', 'https://greenall.example/service/garden-leftovers', '2026-06-12');
