INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_qgrd_card_fx_0614', 'usr_yong_wei', 'credit_card', 'policy_update', 'sub_qgrd_card', 'Historical foreign-currency preauthorization reminder', 'A preauthorization by an overseas drainage-fittings merchant may have a delay before posting; verify it against the order.', '{"card_id": "card_qgrd_01", "tx_id": "tx_qgrd_fx"}', '2026-06-14T01:35:00Z', 0);
