 ('ntf_qgrd_paver_mismatch_0614','usr_yong_wei','ecommerce','price_change',NULL,'Gray permeable paver stock specification update','The in-stock batch is 200×100×60mm, while the site sample is 230×115×60mm; the supplier is awaiting the remeasurement results.','{"state":"dimension_mismatch"}','2026-06-14T04:15:00Z',0),
 ('ntf_qgrd_doc1','usr_yong_wei','email','policy_update',NULL,'Authorization letter for the contracting entity still missing its signature page','Keep pending verification until it is completed.','{"document":"authorization","status":"missing_page"}','2026-06-12T06:05:00Z',0),
 ('ntf_qgrd_rain1','usr_yong_wei','weather','policy_update',NULL,'Historical weather can only serve as observation context','Construction conclusions still require benchmark elevation, grading, drainage-channel connection, and ponding records.','{"rule":"weather_not_acceptance"}','2026-06-14T05:00:00Z',1);
